87	bool validate_single_pem(std::string_view content,
88	                         const std::vector<unsigned char>& der) {
89	    enum class State { BeforeMarker, InBody, AfterMarker };
90	    State state = State::BeforeMarker;
91	    std::string base64;
92	    size_t start = 0;
93	    while (true) {
94	        size_t newline = content.find('\n', start);
