103	            ++begin;
104	        }
105	        while (end > begin &&
106	               std::isspace(static_cast<unsigned char>(line[end - 1]))) {
107	            --end;
108	        }
109	        std::string_view trimmed = line.substr(begin, end - begin);
110	
111	        switch (state) {
112	            case State::BeforeMarker:
113	                if (!trimmed.empty()) {
114	                    if (trimmed != kPemBegin) return false;
115	                    state = State::InBody;
116	                }
117	                break;
118	            case State::InBody:
